# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Download the character stock icons nasmashmate.com shows in its character picker
#          (64x64 PNGs) into pkgs/ds/data/char_icons/, one file per character.
# Usage: `ds data char_icon` (calls `scrape_char_icons()`); look an icon up with
#        `ds.data.char_icon_path("little_mac")`, or the `char_icon` column of char.parquet.
# ---------------------------------------------------------------------------
# Site notes: context the code doesn't show (findings, decisions), as of Nov 2026.
# Re-check against the live site if a download fails.
#
# How the site behaves:
# - nasmashmate.com is a Next.js app. Every icon is a plain static file,
#   https://nasmashmate.com/characters/<name>.png (64x64 RGBA PNG, 4-8 KB), where <name> is
#   the game's internal fighter name (Steve = pickel, Kazuya = demon, Bowser = koopa).
#   No headless browser needed. The pages show them through /_next/image (resized); we take
#   the originals.
# - The picker's full list is not in the leaderboard HTML (that only has the characters of
#   the players on screen). It is a JS object in one of the page's script chunks, display
#   name -> <name> (ends with `Random:"random"`): 86 characters plus Random. `SITE_CHAR_ICON`
#   below was built from it by matching names to char.parquet.
# - The site has one icon for Pokemon Trainer and one for Pyra/Mythra, no per-Pokemon or
#   separate Pyra / Mythra icons (checked: pzenigame, pfushigisou, plizardon, elight -> 404).
#   So our three pt_* ids share one file, and pyra / mythra share another (`SHARED_FILE`).
# - robots.txt: `User-agent: *` is allowed everywhere except /admin, /api/ and /settings.
#   Terms of service not reviewed. The icons are the game's own stock icons.
#
# Decisions:
# - The id -> site name map is written here, not scraped: the script chunk's file name
#   changes with every site deploy, and the internal names don't change.
# - Files are named by our char id, not the site's name, so a path is readable without the map.
# - One request per file with a short pause; this runs by hand, rarely (`ds data char_icon`).
from __future__ import annotations

import time
from typing import TYPE_CHECKING

import httpx2
import polars as pl

from ds.util import http

if TYPE_CHECKING:
    from pathlib import Path

CHAR_ICON_URL = "https://nasmashmate.com/characters/{name}.png"
USER_AGENT = "Mozilla/5.0 (compatible; delulu-smash-char-icon-scraper)"
PNG_MAGIC = b"\x89PNG\r\n\x1a\n"
# Seconds between downloads, to go easy on the site
REQUEST_PAUSE = 0.2

