# Site icons that several of our char ids share -> the file's name (others: the char id)
SHARED_FILE: dict[str, str] = {"ptrainer": "pokemon_trainer", "eflame": "pyra_mythra"}


def char_icon_file(char_id: str) -> str:
    """The icon's file name for a char id: 'little_mac.png' (pt_*: 'pokemon_trainer.png')."""
    if char_id not in SITE_CHAR_ICON:
        raise ValueError(f"no icon for char id {char_id!r}; add it to SITE_CHAR_ICON in ds.data.raw.smashmate")
    return f"{SHARED_FILE.get(SITE_CHAR_ICON[char_id], char_id)}.png"


def scrape_char_icons(dest: Path) -> pl.DataFrame:
    """Download every character's icon into dest (created if missing), overwriting files there.

    Returns one row per file: file, site_name, bytes, char_ids (the char ids that use it).
    """
    dest.mkdir(parents=True, exist_ok=True)
    by_file: dict[str, tuple[str, list[str]]] = {}
    for char_id, site_name in SITE_CHAR_ICON.items():
        by_file.setdefault(char_icon_file(char_id), (site_name, []))[1].append(char_id)

    rows = []
    with httpx2.Client(headers={"User-Agent": USER_AGENT}, timeout=30, follow_redirects=True) as client:
        for file, (site_name, char_ids) in by_file.items():
            url = CHAR_ICON_URL.format(name=site_name)
            with http.request("GET", url, source="smashmate", name=f"icon {site_name}", client=client) as (resp, _):
                resp.raise_for_status()
            if not resp.content.startswith(PNG_MAGIC):  # eg the site's HTML 404 page
                raise ValueError(f"{resp.url} did not return a PNG")
            (dest / file).write_bytes(resp.content)
            rows.append({"file": file, "site_name": site_name, "bytes": len(resp.content), "char_ids": char_ids})
            time.sleep(REQUEST_PAUSE)
    return pl.DataFrame(rows)
